package com.jobsphere.config;
import com.jobsphere.entity.User;import com.jobsphere.repository.UserRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.time.LocalDateTime;
@Configuration public class AdminSeeder { @Bean CommandLineRunner seedAdmins(UserRepository repo){return args->{BCryptPasswordEncoder e=new BCryptPasswordEncoder();seed(repo,e,"admin1@jobsphere.com","JOBSPHERE Administrator 1");seed(repo,e,"admin2@jobsphere.com","JOBSPHERE Administrator 2");};}private void seed(UserRepository r,BCryptPasswordEncoder e,String email,String name){User u=r.findByEmailIgnoreCase(email).orElseGet(User::new);if(u.id==null){u.fullName=name;u.email=email;u.passwordHash=e.encode("Admin@123");u.role=User.Role.ADMIN;u.active=true;u.createdAt=LocalDateTime.now();r.save(u);}else{boolean changed=false;if(u.role!=User.Role.ADMIN){u.role=User.Role.ADMIN;changed=true;}if(!Boolean.TRUE.equals(u.active)){u.active=true;changed=true;}if(changed)r.save(u);}} }
